export const provinciasArgentina = Array.from(
  new Map(
    localidadesArgentina.map((l) => [
      l.provinciaId,
      { id: l.provinciaId, nombre: l.provincia },
    ])
  ).values()
).sort((a, b) => a.nombre.localeCompare(b.nombre, "es"));

export function localidadesPorProvincia(provinciaId: string) {
  return localidadesArgentina.filter((l) => l.provinciaId === provinciaId);
}
